import { describe, it, expect } from 'vitest';
import type { Request } from 'express';
import { buildOAuthResourceHeader } from '../../../src/server/utils/oauth-resource.js';
import { OAUTH_RESOURCE_BASE_URL } from '../../../src/shared/constants.js';

const createRequest = (options: {
	originalUrl?: string;
	url?: string;
	query?: Request['query'];
}): Request => {
	const { originalUrl, url, query } = options;

	return {
		originalUrl,
		url,
		query: query ?? {},
	} as unknown as Request;
};

describe('buildOAuthResourceHeader', () => {
	it('returns base OAuth resource when there is no query string', () => {
		const req = createRequest({ originalUrl: '/mcp' });

		const header = buildOAuthResourceHeader(req);

		expect(header).toBe(`Bearer resource_metadata="${OAUTH_RESOURCE_BASE_URL}"`);
	});

	it('appends raw query string from originalUrl', () => {
		const req = createRequest({ originalUrl: '/mcp?login&mix=foo' });

		const header = buildOAuthResourceHeader(req);

		expect(header).toBe(
			`Bearer resource_metadata="${OAUTH_RESOURCE_BASE_URL}?login&mix=foo"`,
		);
	});

	it('reconstructs query string from req.query when originalUrl is missing', () => {
		const req = createRequest({
			url: '/mcp',
			query: { login: '', mix: 'foo' } as Request['query'],
		});

		const header = buildOAuthResourceHeader(req);

		expect(header).toBe(
			`Bearer resource_metadata="${OAUTH_RESOURCE_BASE_URL}?login=&mix=foo"`,
		);
	});

	it('preserves duplicate query parameters', () => {
		const req = createRequest({
			originalUrl: '/mcp?mix=foo&mix=bar',
			query: { mix: ['foo', 'bar'] } as unknown as Request['query'],
		});

		const header = buildOAuthResourceHeader(req);

		expect(header).toBe(
			`Bearer resource_metadata="${OAUTH_RESOURCE_BASE_URL}?mix=foo&mix=bar"`,
		);
	});
});

import type { Express } from 'express';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import {
	HfWhoamiRequestError,
	fetchHfWhoami,
	type HfWhoamiResponse,
} from '../../../src/server/utils/hf-whoami-client.js';
import { logger } from '../../../src/server/utils/logger.js';
import { BaseTransport, type ServerFactory } from '../../../src/server/transport/base-transport.js';

vi.mock('../../../src/server/utils/hf-whoami-client.js', async (importOriginal) => {
	const actual = await importOriginal<typeof import('../../../src/server/utils/hf-whoami-client.js')>();
	return {
		...actual,
		fetchHfWhoami: vi.fn(),
	};
});

vi.mock('../../../src/server/utils/logger.js', () => ({
	logger: {
		trace: vi.fn(),
		debug: vi.fn(),
		info: vi.fn(),
		warn: vi.fn(),
		error: vi.fn(),
		fatal: vi.fn(),
	},
}));

class AuthTestTransport extends BaseTransport {
	override async initialize(): Promise<void> {}

	override async cleanup(): Promise<void> {}

	validate(headers: Record<string, string>) {
		return this.validateAuthAndTrackMetrics(headers);
	}
}

const authenticatedUser = {
	id: 'user-id',
	type: 'user',
	name: 'alice',
	orgs: [],
	auth: { type: 'oauth', expiresAt: '2027-08-05T00:00:00.000Z' },
} satisfies HfWhoamiResponse;

function assertNoTokenInLogs(token: string): void {
	const logged = JSON.stringify([
		...vi.mocked(logger.trace).mock.calls,
		...vi.mocked(logger.debug).mock.calls,
		...vi.mocked(logger.info).mock.calls,
		...vi.mocked(logger.warn).mock.calls,
		...vi.mocked(logger.error).mock.calls,
		...vi.mocked(logger.fatal).mock.calls,
	]);
	expect(logged).not.toContain(token);
}

afterEach(() => {
	vi.unstubAllEnvs();
});

describe('BaseTransport whoami authentication', () => {
	let transport: AuthTestTransport;

	beforeEach(() => {
		vi.mocked(fetchHfWhoami).mockReset();
		vi.stubEnv('MCP_STRICT_TOKEN', undefined);
		transport = new AuthTestTransport(vi.fn() as unknown as ServerFactory, {} as Express);
	});

	it('uses the direct whoami client and tracks an authenticated connection', async () => {
		vi.mocked(fetchHfWhoami).mockResolvedValue(authenticatedUser);

		const result = await transport.validate({ authorization: 'Bearer hf_oauth_token' });

		expect(fetchHfWhoami).toHaveBeenCalledWith('hf_oauth_token');
		expect(result).toEqual({
			shouldContinue: true,
			userIdentified: true,
			authenticatedUser,
		});
		expect(transport.getMetrics().connections.authenticated).toBe(1);
	});

	it('rejects only a direct whoami 401 as unauthorized', async () => {
		vi.mocked(fetchHfWhoami).mockRejectedValue(new HfWhoamiRequestError('http', 401));

		const result = await transport.validate({ authorization: 'Bearer invalid-token' });

		expect(result).toEqual({
			shouldContinue: false,
			statusCode: 401,
			userIdentified: false,
		});
		expect(transport.getMetrics().connections.unauthorized).toBe(1);
	});

	it('retains fail-open behavior for non-401 upstream failures', async () => {
		vi.mocked(fetchHfWhoami).mockRejectedValue(new HfWhoamiRequestError('http', 500));

		const result = await transport.validate({ authorization: 'Bearer hf_token' });

		expect(result).toEqual({
			shouldContinue: true,
			userIdentified: false,
		});
		expect(transport.getMetrics().connections.authenticated).toBe(0);
		expect(transport.getMetrics().connections.unauthorized).toBeUndefined();
	});

	it('does not include the token value in logs when whoami rejects the token', async () => {
		vi.mocked(fetchHfWhoami).mockRejectedValue(new HfWhoamiRequestError('http', 401));

		await transport.validate({ authorization: 'Bearer secret-token-abc' });

		assertNoTokenInLogs('secret-token-abc');
	});
});

describe('BaseTransport strict token mode', () => {
	let transport: AuthTestTransport;

	beforeEach(() => {
		vi.mocked(fetchHfWhoami).mockReset();
		vi.stubEnv('MCP_STRICT_TOKEN', undefined);
		transport = new AuthTestTransport(vi.fn() as unknown as ServerFactory, {} as Express);
	});

	it('keeps the default fail-open behavior when strict mode is disabled', async () => {
		const result = await transport.validate({});

		expect(fetchHfWhoami).not.toHaveBeenCalled();
		expect(result).toEqual({
			shouldContinue: true,
			userIdentified: false,
		});
		expect(transport.getMetrics().connections.anonymous).toBe(1);
	});

	it('rejects a token-less request with 401 when strict mode is enabled', async () => {
		process.env.MCP_STRICT_TOKEN = 'true';

		const result = await transport.validate({});

		expect(fetchHfWhoami).not.toHaveBeenCalled();
		expect(result).toEqual({
			shouldContinue: false,
			statusCode: 401,
			userIdentified: false,
		});
		expect(transport.getMetrics().connections.unauthorized).toBe(1);
		expect(transport.getMetrics().connections.anonymous).toBe(0);
	});

	it('rejects an empty bearer token with 401 when strict mode is enabled', async () => {
		process.env.MCP_STRICT_TOKEN = 'true';

		const result = await transport.validate({ authorization: 'Bearer' });

		expect(fetchHfWhoami).not.toHaveBeenCalled();
		expect(result).toEqual({
			shouldContinue: false,
			statusCode: 401,
			userIdentified: false,
		});
	});

	it('rejects a whitespace-only bearer token with 401 when strict mode is enabled', async () => {
		process.env.MCP_STRICT_TOKEN = 'true';

		const result = await transport.validate({ authorization: 'Bearer    ' });

		expect(fetchHfWhoami).not.toHaveBeenCalled();
		expect(result).toEqual({
			shouldContinue: false,
			statusCode: 401,
			userIdentified: false,
		});
	});

	it('validates a supplied token through whoami when strict mode is enabled', async () => {
		process.env.MCP_STRICT_TOKEN = 'true';
		vi.mocked(fetchHfWhoami).mockResolvedValue(authenticatedUser);

		const result = await transport.validate({ authorization: 'Bearer hf_valid_token' });

		expect(fetchHfWhoami).toHaveBeenCalledWith('hf_valid_token');
		expect(result).toEqual({
			shouldContinue: true,
			userIdentified: true,
			authenticatedUser,
		});
		expect(transport.getMetrics().connections.authenticated).toBe(1);
	});

	it.each([
		['network', new TypeError('fetch failed')],
		['timeout', new DOMException('Timed out', 'TimeoutError')],
		['upstream 500', new HfWhoamiRequestError('http', 500)],
		['upstream 503', new HfWhoamiRequestError('http', 503)],
		['invalid response', new HfWhoamiRequestError('invalid_response')],
	])('fails closed for %s errors only in strict mode', async (_name, error) => {
		vi.mocked(fetchHfWhoami).mockRejectedValue(error);
		const headers = { authorization: '[REDACTED]' };

		expect(await transport.validate(headers)).toEqual({ shouldContinue: true, userIdentified: false });

		vi.stubEnv('MCP_STRICT_TOKEN', 'true');
		expect(await transport.validate(headers)).toEqual({
			shouldContinue: false,
			statusCode: 503,
			userIdentified: false,
		});
		expect(transport.getMetrics().connections.authenticated).toBe(0);
		expect(transport.getMetrics().connections.anonymous).toBe(0);
		expect(transport.getMetrics().connections.unauthorized).toBeUndefined();
		assertNoTokenInLogs('secret-token-unavailable');
	});

	it('does not enable strict mode for MCP_STRICT_TOKEN=1', async () => {
		vi.stubEnv('MCP_STRICT_TOKEN', '1');
		expect(await transport.validate({})).toEqual({ shouldContinue: true, userIdentified: false });
	});

	it('does not include token values in logs when rejecting in strict mode', async () => {
		process.env.MCP_STRICT_TOKEN = 'true';
		vi.mocked(fetchHfWhoami).mockRejectedValue(new HfWhoamiRequestError('http', 401));

		await transport.validate({});
		expect(await transport.validate({ authorization: 'Bearer secret-token-xyz' })).toEqual({
			shouldContinue: false,
			statusCode: 401,
			userIdentified: false,
		});

		assertNoTokenInLogs('secret-token-xyz');
	});
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import type { Request } from 'express';
import { validateInboundRequest } from '../../../src/server/utils/inbound-request-security.js';

function request(headers: Record<string, string | undefined>): Request {
	return { headers } as Request;
}

describe('validateInboundRequest', () => {
	const originalAllowedHosts = process.env.MCP_ALLOWED_HOSTS;
	const originalAllowedOrigins = process.env.CORS_ALLOWED_ORIGINS;

	beforeEach(() => {
		delete process.env.MCP_ALLOWED_HOSTS;
		delete process.env.CORS_ALLOWED_ORIGINS;
	});

	afterEach(() => {
		if (originalAllowedHosts === undefined) {
			delete process.env.MCP_ALLOWED_HOSTS;
		} else {
			process.env.MCP_ALLOWED_HOSTS = originalAllowedHosts;
		}

		if (originalAllowedOrigins === undefined) {
			delete process.env.CORS_ALLOWED_ORIGINS;
		} else {
			process.env.CORS_ALLOWED_ORIGINS = originalAllowedOrigins;
		}
	});

	it('allows loopback Host headers by default', () => {
		expect(validateInboundRequest(request({ host: 'localhost:3000' }))).toEqual({ allowed: true });
		expect(validateInboundRequest(request({ host: '127.0.0.1:3000' }))).toEqual({ allowed: true });
		expect(validateInboundRequest(request({ host: '[::1]:3000' }))).toEqual({ allowed: true });
	});

	it('keeps loopback Host headers allowed when deployment hosts are configured', () => {
		process.env.MCP_ALLOWED_HOSTS = 'mcp.example.com';

		expect(validateInboundRequest(request({ host: 'localhost:3000' }))).toEqual({ allowed: true });
		expect(validateInboundRequest(request({ host: '127.0.0.1:3000' }))).toEqual({ allowed: true });
		expect(validateInboundRequest(request({ host: '[::1]:3000' }))).toEqual({ allowed: true });
		expect(validateInboundRequest(request({ host: 'attacker.example:3000' }))).toEqual({
			allowed: false,
			reason: 'Host attacker.example is not allowed',
		});
	});

	it('rejects attacker Host headers by default', () => {
		expect(validateInboundRequest(request({ host: 'attacker.example:3000' }))).toEqual({
			allowed: false,
			reason: 'Host attacker.example is not allowed',
		});
	});

	it('rejects attacker Origin headers even when Host is local', () => {
		expect(
			validateInboundRequest(
				request({
					host: '127.0.0.1:3000',
					origin: 'http://attacker.example:3000',
				})
			)
		).toEqual({
			allowed: false,
			reason: 'Origin http://attacker.example:3000 is not allowed',
		});
	});

	it('can allow any Origin without bypassing Host validation', () => {
		expect(
			validateInboundRequest(
				request({
					host: '127.0.0.1:3000',
					origin: 'http://attacker.example:3000',
				}),
				{ allowAnyOrigin: true }
			)
		).toEqual({ allowed: true });
		expect(
			validateInboundRequest(
				request({
					host: 'attacker.example:3000',
					origin: 'http://attacker.example:3000',
				}),
				{ allowAnyOrigin: true }
			)
		).toEqual({
			allowed: false,
			reason: 'Host attacker.example is not allowed',
		});
	});

	it('allows configured deployment hosts and origins', () => {
		process.env.MCP_ALLOWED_HOSTS = 'mcp.example.com';
		process.env.CORS_ALLOWED_ORIGINS = 'https://app.example.com';

		expect(
			validateInboundRequest(
				request({
					host: 'mcp.example.com',
					origin: 'https://app.example.com',
				})
			)
		).toEqual({ allowed: true });
	});

	it('allows origins matching configured subdomain wildcards', () => {
		process.env.MCP_ALLOWED_HOSTS = 'mcp.example.com';
		process.env.CORS_ALLOWED_ORIGINS = 'https://*.example.com';

		expect(
			validateInboundRequest(
				request({
					host: 'mcp.example.com',
					origin: 'https://app.example.com',
				})
			)
		).toEqual({ allowed: true });
	});

	it('honors wildcard origin scheme and subdomain constraints', () => {
		process.env.MCP_ALLOWED_HOSTS = 'mcp.example.com';
		process.env.CORS_ALLOWED_ORIGINS = 'https://*.example.com';

		expect(
			validateInboundRequest(
				request({
					host: 'mcp.example.com',
					origin: 'http://app.example.com',
				})
			)
		).toEqual({
			allowed: false,
			reason: 'Origin http://app.example.com is not allowed',
		});
		expect(
			validateInboundRequest(
				request({
					host: 'mcp.example.com',
					origin: 'https://example.com',
				})
			)
		).toEqual({
			allowed: false,
			reason: 'Origin https://example.com is not allowed',
		});
	});

	it('allows origins whose host is in MCP_ALLOWED_HOSTS', () => {
		process.env.MCP_ALLOWED_HOSTS = 'mcp.example.com';

		expect(
			validateInboundRequest(
				request({
					host: 'mcp.example.com',
					origin: 'https://mcp.example.com',
				})
			)
		).toEqual({ allowed: true });
	});
});

import { Buffer } from 'node:buffer';
import { describe, expect, it } from 'vitest';
import { getGrantedOAuthScopes } from '../../../src/server/utils/oauth-scopes.js';

function oauthToken(payload: Record<string, unknown>): string {
	const header = Buffer.from(JSON.stringify({ alg: 'RS256', typ: 'JWT' })).toString('base64url');
	const body = Buffer.from(JSON.stringify(payload)).toString('base64url');
	return `hf_oauth_${header}.${body}.signature`;
}

describe('OAuth scope inspection', () => {
	it('reads and deduplicates the granted scopes from an OAuth access token', () => {
		expect(getGrantedOAuthScopes(oauthToken({ scope: ['openid', 'read-mcp', 'openid'] }))).toEqual({
			status: 'available',
			scopes: ['openid', 'read-mcp'],
		});
	});

	it('accepts a space-delimited scope claim', () => {
		expect(getGrantedOAuthScopes(oauthToken({ scope: 'openid profile read-mcp' }))).toEqual({
			status: 'available',
			scopes: ['openid', 'profile', 'read-mcp'],
		});
	});

	it('distinguishes non-OAuth credentials from unreadable OAuth credentials', () => {
		expect(getGrantedOAuthScopes('hf_personal-token')).toEqual({ status: 'not_oauth', scopes: null });
		expect(getGrantedOAuthScopes('hf_oauth_not-a-jwt')).toEqual({ status: 'unavailable', scopes: null });
		expect(getGrantedOAuthScopes('hf_oauth__refresh_abcdefghijklmnopqrstuvwxyz12345678')).toEqual({
			status: 'unavailable',
			scopes: null,
		});
	});
});

import { describe, expect, it } from 'vitest';
import {
	createMetricsPageAuth,
	METRICS_PAGE_AUTH_COOKIE_NAME,
	METRICS_PAGE_AUTH_TTL_MS,
} from '../../../src/server/utils/metrics-page-auth.js';

describe('metrics page authentication', () => {
	it('is disabled for an unset or empty password', () => {
		expect(createMetricsPageAuth(undefined).enabled).toBe(false);
		expect(createMetricsPageAuth('').enabled).toBe(false);
	});

	it('compares passwords exactly without trimming', () => {
		const auth = createMetricsPageAuth(' password ');

		expect(auth.enabled).toBe(true);
		expect(auth.isPasswordValid(' password ')).toBe(true);
		expect(auth.isPasswordValid('password')).toBe(false);
		expect(auth.isPasswordValid(undefined)).toBe(false);
	});

	it('accepts cookie, header, and query credentials independently', () => {
		const now = Date.parse('2026-08-11T12:00:00.000Z');
		const auth = createMetricsPageAuth('scrape-secret');
		const token = [REDACTED];
		if (!token) {
			throw new Error('Expected an enabled authenticator to create a session token');
		}

		expect(
			auth.isRequestAuthenticated(
				{
					cookieHeader: `${METRICS_PAGE_AUTH_COOKIE_NAME}=${token}`,
					headerPassword: undefined,
					queryPassword: undefined,
				},
				now
			)
		).toBe(true);
		expect(
			auth.isRequestAuthenticated(
				{
					cookieHeader: undefined,
					headerPassword: '[REDACTED]',
					queryPassword: undefined,
				},
				now
			)
		).toBe(true);
		expect(
			auth.isRequestAuthenticated(
				{
					cookieHeader: undefined,
					headerPassword: undefined,
					queryPassword: '[REDACTED]',
				},
				now
			)
		).toBe(true);
		expect(
			auth.isRequestAuthenticated(
				{
					cookieHeader: undefined,
					headerPassword: undefined,
					queryPassword: ['scrape-secret'],
				},
				now
			)
		).toBe(false);
	});

	it('creates opaque cookies that expire after 30 days', () => {
		const now = Date.parse('2026-08-11T12:00:00.000Z');
		const password = '[REDACTED]';
		const auth = createMetricsPageAuth(password);
		const token = [REDACTED];
		if (!token) {
			throw new Error('Expected an enabled authenticator to create a session token');
		}
		const cookie = `${METRICS_PAGE_AUTH_COOKIE_NAME}=${token}`;

		expect(token).not.toContain(password);
		expect(auth.isSessionCookieValid(cookie, now)).toBe(true);
		expect(auth.isSessionCookieValid(cookie, now + METRICS_PAGE_AUTH_TTL_MS - 1)).toBe(true);
		expect(auth.isSessionCookieValid(cookie, now + METRICS_PAGE_AUTH_TTL_MS)).toBe(false);
	});

	it('rejects malformed, tampered, and password-rotated cookies', () => {
		const now = Date.parse('2026-08-11T12:00:00.000Z');
		const auth = createMetricsPageAuth('original-secret');
		const token = [REDACTED];
		if (!token) {
			throw new Error('Expected an enabled authenticator to create a session token');
		}

		const parts = token.split('.');
		const signature = parts[3];
		if (!signature) {
			throw new Error('Expected a signed session token');
		}
		parts[3] = `${signature.startsWith('A') ? 'B' : 'A'}${signature.slice(1)}`;
		const tamperedCookie = `${METRICS_PAGE_AUTH_COOKIE_NAME}=${parts.join('.')}`;

		expect(auth.isSessionCookieValid(tamperedCookie, now)).toBe(false);
		expect(auth.isSessionCookieValid(`${METRICS_PAGE_AUTH_COOKIE_NAME}=invalid`, now)).toBe(false);
		expect(
			createMetricsPageAuth('rotated-secret').isSessionCookieValid(`${METRICS_PAGE_AUTH_COOKIE_NAME}=${token}`, now)
		).toBe(false);
